// Avisos derivados de documentos confirmados, sin escrituras adicionales ni duplicados.
// La campana es una vista de eventos; no se presenta como bandeja de lectura persistente.
function operationalAlerts(){
 const rows=[];
 for(const p of state.plans){
  if(p.status==='CANCELADO')continue;
  const base={planId:p.id,activity:p.activityName||'Actividad',analyst:p.analystName||'Analista'};
  if(p.createdAt?.seconds && p.status!=='CANCELADO')rows.push({...base,id:p.id+':assigned',kind:'ASIGNACION',date:p.createdAt,description:'Actividad asignada por planificación'});
  if(p.startedAt?.seconds)rows.push({...base,id:p.id+':open',kind:'APERTURA',date:p.startedAt,description:'Inicio de actividad confirmado'});
  if(p.finishedAt?.seconds)rows.push({...base,id:p.id+':close',kind:'CIERRE',date:p.finishedAt,description:'Finalización confirmada'});
 }
 return rows.sort((a,b)=>(b.date?.seconds||0)-(a.date?.seconds||0)).slice(0,30);
}
// Bounded conversation watchers: only recent 24 plans, one last-message document per plan.
let communicationsReturnPage='Inicio';
const readState={marks:{},latest:{},stops:new Map(),stopMarks:null,uid:null};
function unreadConversationCount(){return Object.entries(readState.latest).filter(([id,m])=>m&&m.authorId!==state.user?.uid&&readState.marks[id]?.messageId!==m.id).length}
function isArchivedPlan(id){const m=readState.marks[id]||{};const last=readState.latest[id];return m.archived===true&&(!last||last.authorId===state.user?.uid||m.messageId===last.id)}
function assignmentPending(p){if(!p?.createdAt?.seconds||p.status==='CANCELADO')return false;return state.profile?.role==='ANALISTA'&&readState.marks[p.id]?.assignmentSeen!==p.createdAt.seconds}
function unreadForPlan(id){const m=readState.latest[id];return !!(m&&m.authorId!==state.user?.uid&&readState.marks[id]?.messageId!==m.id)}
function clearReadWatches(){readState.stopMarks?.();readState.stopMarks=null;for(const stop of readState.stops.values())stop();readState.stops.clear();readState.marks={};readState.latest={};readState.uid=null}
// V29.0.128: avisos visuales basados en eventos NUEVOS; no escribe en Firebase.
const liveAlerts={readyMessages:new Set(),readyPlans:false,knownPlans:new Set(),seen:new Set(),timers:new Map()};
function resetLiveAlerts(){liveAlerts.readyMessages.clear();liveAlerts.readyPlans=false;liveAlerts.knownPlans.clear();liveAlerts.seen.clear();for(const t of liveAlerts.timers.values())clearTimeout(t);liveAlerts.timers.clear();document.getElementById('psi-live-alerts')?.remove()}
function desktopAlertStatus(){if(!('Notification' in window))return {label:'Avisos internos activos · navegador no compatible',state:'unsupported'};if(!window.isSecureContext)return {label:'Avisos internos activos · requiere HTTPS',state:'unsupported'};return Notification.permission==='granted'?{label:'Avisos activados',state:'granted'}:Notification.permission==='denied'?{label:'Avisos bloqueados · revisar Safari/Chrome',state:'denied'}:{label:'Activar avisos',state:'default'}}
function updateDesktopAlertButton(){const b=document.querySelector('#enableDesktopAlerts');if(!b)return;const status=desktopAlertStatus();b.title=status.label+'; los mensajes internos siempre están disponibles';b.setAttribute('aria-label',status.label);b.dataset.permission=status.state;b.querySelector('.alert-button-label').textContent=status.label;}
function enableDesktopAlerts(){if(!('Notification' in window)){alert('Este navegador no admite notificaciones de escritorio. Los mensajes internos no dependen de este permiso.');return}if(!window.isSecureContext){alert('Las notificaciones requieren HTTPS o localhost.');return}Notification.requestPermission().then(()=>updateDesktopAlertButton()).catch(()=>updateDesktopAlertButton())}
function emitLiveAlert(id,title,detail,planId){if(!state.user||liveAlerts.seen.has(id))return;liveAlerts.seen.add(id);if(liveAlerts.seen.size>300)liveAlerts.seen.delete(liveAlerts.seen.values().next().value);
 let holder=document.getElementById('psi-live-alerts');if(!holder){holder=document.createElement('div');holder.id='psi-live-alerts';holder.setAttribute('aria-live','polite');document.body.appendChild(holder)}
 const card=document.createElement('div');card.className='psi-live-card';const heading=document.createElement('strong');heading.textContent=title;const description=document.createElement('p');description.textContent=detail;const actions=document.createElement('div');const open=document.createElement('button');open.type='button';open.textContent=planId?'Abrir chat':'Ver actividad';const close=document.createElement('button');close.type='button';close.textContent='Cerrar';actions.append(open,close);card.append(heading,description,actions);holder.prepend(card);
 const dismiss=()=>{clearTimeout(liveAlerts.timers.get(id));liveAlerts.timers.delete(id);card.remove()};close.onclick=dismiss;open.onclick=()=>{dismiss();openCommunicationFromNotice(planId)};liveAlerts.timers.set(id,setTimeout(dismiss,12000));
 if(document.hidden&&'Notification' in window&&Notification.permission==='granted'){try{const n=new Notification(title,{body:detail,tag:'psi-'+id});n.onclick=()=>{window.focus();openCommunicationFromNotice(planId);n.close()}}catch(e){console.warn('Aviso del sistema:',e.message)}}
}
function openCommunicationFromNotice(planId){
 navigate94('Centro de Comunicaciones');
 if(planId&&state.plans.some(p=>p.id===planId)){
  // Open the actual conversation; never mark another activity as read.
  loadCommunication(planId);
 }
}
function inspectNewPlans(plans){const current=new Set(plans.map(p=>p.id));if(liveAlerts.readyPlans&&state.profile?.role==='ANALISTA')for(const p of plans){if(!liveAlerts.knownPlans.has(p.id)&&assignmentPending(p)&&p.createdAt?.seconds*1000>Date.now()-120000)emitLiveAlert('plan:'+p.id,'📅 Nueva actividad asignada',p.activityName||'Nueva planificación',p.id)}liveAlerts.knownPlans=current;liveAlerts.readyPlans=true}
function inspectNewMessage(planId,m){const initialized=liveAlerts.readyMessages.has(planId);liveAlerts.readyMessages.add(planId);if(!initialized||!m?.id||m.authorId===state.user?.uid||readState.marks[planId]?.messageId===m.id)return;const when=m.createdAt?.seconds*1000||0;if(when<Date.now()-120000)return;const plan=state.plans.find(p=>p.id===planId);emitLiveAlert('message:'+planId+':'+m.id,'💬 Nuevo mensaje',`${plan?.activityName||'Actividad'} · ${m.authorName||'Nuevo mensaje'}`,planId)}
