function refreshReadWatches(){if(!state.user||!state.profile)return;const eligible=state.plans.filter(p=>p.status!=='CANCELADO').sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,80);const ids=new Set(eligible.map(p=>p.id));for(const [id,stop] of readState.stops)if(!ids.has(id)){stop();readState.stops.delete(id);delete readState.latest[id]}
 for(const id of ids){if(readState.stops.has(id))continue;readState.stops.set(id,watchCommunicationLastMessage(id,m=>{readState.latest[id]=m;inspectNewMessage(id,m);if(['Centro de Comunicaciones','Inicio'].includes(state.page))main();else updateBellBadge()},e=>console.warn('Lectura de chat:',e.message)))}
}
