// V151: carta ambiental identificable, vinculada y visible en el panel común.
const ENV_ID='MC1602-08-METALES-EI313';
let envJourneyCache={card:null,record:null,balanceCard:null,balanceRecord:null,dboCard:null,dboRecord:null,microCard:null,microRecord:null,fridgeCard:null,fridgeRecord:null,standardsFridgeCard:null,standardsFridgeRecord:null,agarFridgeCard:null,agarFridgeRecord:null,balance227Settings:null,balance227Record:null,ntkSettings:null,ntkDaily:null,hachSettings:null,hachDaily:null,date:'',loaded:false};
let envJourneyLoading=false;
let specializedWatchStops=[];
let specializedWatchDate='';
let specializedWatchGeneration=0;
const specializedConfirmedStates=new Map();
const specializedDailySources=[
 ['environmentalRecords',[[ENV_ID,'record'],[balanceEnvironmentalCardId,'balanceRecord'],[dboEnvironmentalCardId,'dboRecord'],[microEnvironmentalCardId,'microRecord'],[fridgeEnvironmentalCardId,'fridgeRecord'],[standardsFridgeEnvironmentalCardId,'standardsFridgeRecord'],[agarFridgeEnvironmentalCardId,'agarFridgeRecord'],[freezerEnvironmentalCardId,'freezerRecord']]],
 ['balance227Records',[[BALANCE227_ID,'balance227Record']]],
 ['incubator306Records',[[INC306_ID,'inc306Daily']]],
 ['thermalControlRecords',[[NTK_ID,'ntkDaily'],[HACH_ID,'hachDaily'],[N105_ID,'n105Daily'],[OVEN316_ID,'ovenDaily'],[MUFLA328_ID,'muflaDaily'],[BATH364_ID,'bath364Daily'],[MICRO365_ID,'micro365Daily'],[DQO360_ID,'dqo360Daily']]]
];
// Escuchar exactamente los documentos del día (no consultar historiales completos).
// La actualización de una carta en otra PC modifica solo el panel de la jornada.
function stopSpecializedDailyWatches(){specializedConfirmedStates.clear();specializedWatchGeneration++;specializedWatchStops.forEach(stop=>stop());specializedWatchStops=[];specializedWatchDate='';}
function startSpecializedDailyWatches(date){
 if(specializedWatchDate===date)return;
 stopSpecializedDailyWatches();specializedWatchDate=date;
 const generation=specializedWatchGeneration;
 for(const [collectionName,entries] of specializedDailySources){
  for(const [cardId,field] of entries){
   const stop=onSnapshot(doc(db,collectionName,date+'_'+cardId),{includeMetadataChanges:true},snap=>{
    if(generation!==specializedWatchGeneration||state.page!=='Mi Jornada')return;
    // Escuchar también la confirmación del servidor tras una escritura propia.
    // Sin includeMetadataChanges:true, la confirmación puede ser solo metadatos
    // y el equipo que guardó permanece PENDIENTE hasta F5.
    // No presentar como confirmado un dato que todavía esté pendiente en caché local.
    if(snap.metadata.hasPendingWrites)return;
    const value=snap.exists()?snap.data():null;
    if(envJourneyCache.date!==date||!envJourneyCache.loaded){
     if(!envJourneyLoading)refreshEnvironmentalJourney(date);
     return;
    }
    // Una escritura local puede actualizar el cache antes del ACK de Firebase.
    // El ACK debe refrescar la pantalla aunque el contenido sea idéntico.
    const key=collectionName+'/'+date+'_'+cardId;
    const signature=JSON.stringify(value);
    const confirmedPreviously=specializedConfirmedStates.get(key);
    specializedConfirmedStates.set(key,signature);
    const before=envJourneyCache[field];
    envJourneyCache[field]=value;
    if(JSON.stringify(before)!==signature||confirmedPreviously!==signature||!snap.metadata.fromCache){
     scheduleSpecializedPanelUpdate();
    }
   },err=>console.warn('Sincronización carta '+cardId+':',err.message));
   specializedWatchStops.push(stop);
  }
 }
}
let specializedRenderScheduled=false;
function scheduleSpecializedPanelUpdate(){
 if(specializedRenderScheduled)return;
 specializedRenderScheduled=true;
 requestAnimationFrame(()=>{
  specializedRenderScheduled=false;
  if(state.page!=='Mi Jornada')return;
  // Mantener formularios y expedientes abiertos sin reiniciar toda la página.
  const oldPanel=document.querySelector('.cc-journey-panel');
  if(!oldPanel)return;
  const date=state.journeyDate||new Date().toLocaleDateString('en-CA');
  const selected=state.profile.role==='JEFE'?(state.journeyAnalyst||''):state.user.uid;
  const plans=state.plans.filter(p=>p.date===date&&p.status!=='CANCELADO'&&(!selected||p.analystId===selected));
  const holder=document.createElement('div');holder.innerHTML=journeyControlsPanel(date,plans);
  const newPanel=holder.firstElementChild;
  if(newPanel){
   const expanded=oldPanel.querySelector('.cc-compact-details')?.open;
   if(expanded===false)newPanel.querySelector('.cc-compact-details')?.removeAttribute('open');
   // Conservar los manejadores ya instalados al sustituir solo el panel.
   // Sin esto, el panel actualizado pierde los botones de las cartas especializadas.
   const oldButtons=[...oldPanel.querySelectorAll('button')];
   const newButtons=[...newPanel.querySelectorAll('button')];
   newButtons.forEach((button,index)=>{
    const previous=oldButtons[index];
    if(previous&&previous.className===button.className&&previous.onclick)button.onclick=previous.onclick;
   });
   oldPanel.replaceWith(newPanel);
   newPanel.querySelectorAll('.cc-journey-open').forEach(btn=>btn.onclick=()=>openControlMulti(state.controlCards.find(c=>c.id===btn.dataset.cardId),date));
   newPanel.querySelectorAll('.cc-go-controls').forEach(btn=>btn.onclick=()=>navigate94('Cartas de Control'));
  }
 });
}

