 document.querySelectorAll('.env-links').forEach(b=>b.onclick=()=>openEnvironmental({date,role:state.profile.role,activities:state.catalog.filter(x=>x.active!==false),section:'links',cardId:b.dataset.envId||ENV_ID}).catch(e=>alert(e.message)));
 document.querySelectorAll('.env-open').forEach(b=>b.onclick=()=>openEnvironmental({date,role:state.profile.role,activities:state.catalog.filter(x=>x.active!==false),cardId:b.dataset.envId||ENV_ID}).catch(e=>alert(e.message)));
 // V178: recuperación idempotente de acciones JEFE después de actualizaciones de vista.
 // La delegación evita perder manejadores cuando se vuelve a construir la lista.
 const thermalGrid=document.querySelector('#ccMasterGrid');
 if(thermalGrid && boss){
   const ensureThermalActions=()=>{
     for(const [prefix,handler] of [['ntk',()=>openNTKSettings('config',state.catalog)],['hach',()=>openHACHSettings('config',state.catalog)],['n105',()=>openN105Settings('config',state.catalog)],['oven316',()=>openOVEN316Settings('config',state.catalog)]]){
       const open=thermalGrid.querySelector('#'+prefix+'Open');
       const actions=open?.closest('.env-actions');
       if(actions && !actions.querySelector('#'+prefix+'Settings')){
         const button=document.createElement('button');
         button.type='button';button.className='outline';button.id=prefix+'Settings';
         button.textContent='✎ Editar configuración metrológica';
         actions.appendChild(button);
       }
     }
   };
   ensureThermalActions();
   thermalGrid.addEventListener('click',event=>{
     const id=event.target.closest('button')?.id;
     if(id==='ntkSettings'){event.preventDefault();openNTKSettings('config',state.catalog)}
     if(id==='hachSettings'){event.preventDefault();openHACHSettings('config',state.catalog)}
     if(id==='n105Settings'){event.preventDefault();openN105Settings('config',state.catalog)}
     if(id==='oven316Settings'){event.preventDefault();openOVEN316Settings('config',state.catalog)}
   });
   const observer=new MutationObserver(()=>ensureThermalActions());
   observer.observe(thermalGrid,{childList:true,subtree:true});
   // Se desconecta cuando la vista es reemplazada para evitar observadores obsoletos.
   const cleanup=new MutationObserver(()=>{if(!thermalGrid.isConnected){observer.disconnect();cleanup.disconnect()}});
   cleanup.observe(document.querySelector('.content'),{childList:true});
 }
