   const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;
   const lines=[];for(let page=1;page<=Math.min(pdf.numPages,15);page++){
    const content=await(await pdf.getPage(page)).getTextContent();
    const text=content.items.map(i=>i.str||'').join(' ');lines.push({page,text});
   }
   const whole=lines.map(x=>x.text).join(' '),normal=x=>String(x||'').toLowerCase().replace(/[^a-z0-9]/g,'');
   if(whole.trim().length<90){box.textContent='El PDF no contiene suficiente texto seleccionable. Es posible que sea escaneado; complete los datos manualmente.';return;}
   const suggestions=[];
   const patterns=[
    ['coverageFactor',/(?:coverage factor|factor de cobertura)\s*[:=]?\s*k?\s*[=:]?\s*(\d(?:[.,]\d+)?)/i],
    ['confidence',/(?:confidence level|nivel de confianza|confidence interval)\s*[:=]?\s*(\d{2}(?:[.,]\d+)?)\s*%/i],
    ['uncertainty',/(?:expanded uncertainty|incertidumbre expandida)\s*[:=±]?\s*([0-9]+(?:[.,][0-9]+)?)/i],
    ['coaNumber',/(?:certificate (?:number|no\.?|#)|certificado (?:n[úu]mero|n[.º°o]*))\s*[:#]?\s*([A-Z0-9][A-Z0-9\/-]{3,})/i]
   ];
   for(const [key,re] of patterns){for(const line of lines){const match=line.text.match(re);if(match){suggestions.push({key,value:match[1].replace(',','.'),page:line.page});break;}}}
   const lot=form.elements.namedItem('lot')?.value,brand=form.elements.namedItem('brand')?.value;
   const lotMatch=lot&&normal(whole).includes(normal(lot));
   const brandMatch=brand&&normal(whole).includes(normal(brand));
