function openReplenishment(item){
 if(!item)return;
 const root=document.querySelector('#modalRoot');
 root.innerHTML=`<div class="modal-overlay"><form class="catalog-modal reagent-pro" id="replenishForm"><div class="modal-head"><div><span class="eyebrow">INVENTARIO · ENTRADA ADMINISTRATIVA</span><h2>Reponer lote existente</h2><p class="muted">${esc(item.name)} · ${esc(item.code)} · lote ${esc(item.lot)}</p></div><button type="button" class="icon-btn" id="closeEntry">×</button></div><div class="catalog-form-body"><div class="form-section"><h3>Entrada trazable</h3><p>Saldo confirmado: <strong>${Number(item.stock)} ${esc(item.unit)}</strong>. La entrada incrementará exclusivamente este lote. Para un lote diferente, cree una nueva ficha con el mismo producto.</p><div class="form-grid"><label>Cantidad recibida (${esc(item.unit)})<input name="quantity" type="number" min="0.000001" step="any" required></label><label>Observación / documento de recepción<input name="notes" maxlength="500" required placeholder="Ej. OC y fecha de recepción"></label></div></div></div><div id="entryError" class="form-error"></div><div class="modal-actions"><button type="button" class="outline" id="cancelEntry">Cancelar</button><button type="submit" class="primary" id="submitEntry">Confirmar entrada en Firebase</button></div></form></div>`;
 const form=root.querySelector('#replenishForm'),close=()=>root.innerHTML='';root.querySelector('#closeEntry').onclick=close;root.querySelector('#cancelEntry').onclick=close;
 const operationId=crypto.randomUUID();
 form.onsubmit=async e=>{e.preventDefault();const btn=root.querySelector('#submitEntry');btn.disabled=true;btn.textContent='Confirmando…';try{const result=await replenishReagent({reagentId:item.id,quantity:Number(form.elements.namedItem('quantity').value),notes:form.elements.namedItem('notes').value.trim(),operationId},state.user.uid);close();alert(result.duplicate?'Entrada previamente confirmada.':'Entrada confirmada. Nuevo saldo: '+result.stock+' '+item.unit)}catch(err){root.querySelector('#entryError').textContent=err.message;btn.disabled=false;btn.textContent='Reintentar entrada'}};
}
// Menú de acciones adaptativo: posición fija para evitar recortes en tablas con scroll.
function bindInventoryActionMenus(){
 const menus=[...document.querySelectorAll('.inventory-action-menu')];
 if(!menus.length)return;
 const closeAll=(except=null)=>menus.forEach(m=>{if(m!==except){m.open=false;const list=m.querySelector('.inventory-action-list');if(list)list.style.visibility='';}});
 menus.forEach(menu=>{
   const summary=menu.querySelector('summary');
   summary.addEventListener('click',e=>{
     e.preventDefault();
     const opening=!menu.open;
     closeAll(menu);
     if(!opening){menu.open=false;return;}
     menu.open=true;
     const list=menu.querySelector('.inventory-action-list');
     if(!list)return;
     list.style.visibility='hidden';
     const rect=summary.getBoundingClientRect();
     const width=Math.min(230,Math.max(175,window.innerWidth-24));
     const height=list.getBoundingClientRect().height;
     const left=Math.max(12,Math.min(rect.right-width,window.innerWidth-width-12));
     const below=window.innerHeight-rect.bottom-12;
     const above=rect.top-12;
     const top=below>=height||below>=above?Math.min(rect.bottom+6,window.innerHeight-height-8):Math.max(8,rect.top-height-6);
     Object.assign(list.style,{position:'fixed',width:width+'px',left:left+'px',right:'auto',top:Math.max(8,top)+'px',visibility:'visible'});
   });
 });
 // Un solo manejador por render, eliminado al reemplazar la vista.
 const onPointer=e=>{if(!document.querySelector('.inventory-action-menu')?.isConnected){cleanup();return;}if(!e.target.closest('.inventory-action-menu'))closeAll();};
 const onKey=e=>{if(e.key==='Escape')closeAll();};
 const onScroll=e=>{if(menus.some(m=>m.open))closeAll();};
 const cleanup=()=>{document.removeEventListener('pointerdown',onPointer);document.removeEventListener('keydown',onKey);window.removeEventListener('scroll',onScroll,true);window.removeEventListener('resize',onScroll);};
 document.addEventListener('pointerdown',onPointer);
 document.addEventListener('keydown',onKey);
 window.addEventListener('scroll',onScroll,true);
 window.addEventListener('resize',onScroll);
}
