function timeFields(minutes, prefix){const n=Math.max(0,Number(minutes)||0);return `<div class="time-pair"><label>Horas<input name="${prefix}Hours" type="number" min="0" max="24" step="1" value="${Math.floor(n/60)}" required></label><label>Minutos<select name="${prefix}Minutes">${[0,15,30,45].map(v=>`<option value="${v}" ${n%60===v?'selected':''}>${String(v).padStart(2,'0')} min</option>`).join('')}${n%60%15!==0?`<option value="${n%60}" selected>${n%60} min (existente)</option>`:''}</select></label></div>`}
function formatDuration(minutes){const n=Number(minutes)||0;return `${Math.floor(n/60)} h ${String(n%60).padStart(2,'0')} min`}
// V29.0.131: lectura unificada de vínculos desde inventario y ficha técnica.
// No escribe en Firebase ni modifica versiones históricas.
function effectiveCatalogReactives(item){
 const byId=new Map();
 for(const link of (Array.isArray(item.reactives)?item.reactives:[])){
  const reagent=state.reagents.find(r=>r.id===link.reagentId)||state.reagents.find(r=>r.code===link.code&&r.lot===link.lot);
  const key=reagent?.id||link.reagentId||`${link.code||''}|${link.lot||''}`;
  byId.set(key,{...link,...(reagent?{name:reagent.name,code:reagent.code,lot:reagent.lot,unit:reagent.unit,status:reagent.status,stock:reagent.stock,reagentId:reagent.id}:{}),origin:'FICHA'});
 }
 for(const reagent of state.reagents){
  if(!Array.isArray(reagent.activityIds)||!reagent.activityIds.includes(item.id))continue;
  if(!byId.has(reagent.id))byId.set(reagent.id,{reagentId:reagent.id,name:reagent.name,code:reagent.code,lot:reagent.lot,unit:reagent.unit,status:reagent.status,stock:reagent.stock,quantity:null,origin:'INVENTARIO'});
 }
 return [...byId.values()];
}
function catalogLinksSummary(item){const rs=effectiveCatalogReactives(item);if(!rs.length)return '<small class="table-sub">Sin reactivos vinculados</small>';return `<details class="catalog-linked-preview"><summary>${rs.length} reactivo(s) vinculado(s) · Ver detalle</summary><div>${rs.map(r=>`<div class="linked-chip"><strong>${esc(r.name||r.code||'Producto')}</strong> <span>${esc(r.code||'')} · Lote ${esc(r.lot||'—')} · ${r.quantity!=null&&r.quantity!==''&&Number(r.quantity)>0?`${esc(r.quantity)} ${esc(r.unit||'')} / ${r.basis==='MUESTRA'?'muestra':'actividad'}`:'Sin cantidad prevista (se medirá en Mi Jornada)'} · ${r.origin==='INVENTARIO'?'Vinculado desde inventario':'Ficha técnica'}${r.status==='INACTIVO'?' · Lote inactivo':''}</span></div>`).join('')}</div></details>`}
