function selectPlanAnalyst(plan){
 return new Promise(resolve=>{
  const wrap=document.createElement('div');wrap.className='plan-select-backdrop';
  const options=planAnalysts().filter(a=>a.id!==plan.analystId).map(a=>{
   const trial={...plan,analystId:a.id,analystName:a.name||a.email};
   const warnings=planWarnings(trial,plan.id);
   return `<option value="${esc(a.id)}" ${warnings.length?'disabled':''}>${esc(a.name||a.email)}${warnings.length?' — '+esc(warnings[0]):' — disponible'}</option>`;
  }).join('');
  wrap.innerHTML=`<div class="plan-select-card" role="dialog" aria-modal="true"><h3>Reasignar actividad</h3><p>${esc(plan.activityName)} · ${ptime(plan.startMin)}–${ptime(plan.endMin)}</p><label>Nuevo analista<select id="planTarget"><option value="">Seleccione analista disponible</option>${options}</select></label><p class="muted">Se comprueban sección autorizada, cruces y límite de 8 horas.</p><div class="plan-select-actions"><button type="button" id="planClose">Cancelar</button><button type="button" class="primary" id="planChoose">Guardar reasignación</button></div></div>`;
  document.body.appendChild(wrap);
  const finish=v=>{wrap.remove();resolve(v)};
  wrap.querySelector('#planClose').onclick=()=>finish(null);
  wrap.querySelector('#planChoose').onclick=()=>{const v=wrap.querySelector('#planTarget').value;if(v)finish(v)};
  wrap.onclick=e=>{if(e.target===wrap)finish(null)};
 });
}
function bindPlanner(){const $=id=>document.getElementById(id);$('planDate').onchange=e=>{state.planDate=e.target.value;state.planMessage='';main()};$('planRefresh').onclick=async()=>{try{state.analysts=await readAnalysts();state.competencies=await readCompetencies();state.planMessage='Perfiles y competencias actualizados.'}catch(e){state.planMessage=e.message}main()};
 const form=$('planForm'),area=$('planArea'),activity=$('planActivity'),start=$('planStart'),end=$('planEnd'),analyst=$('planAnalyst'),search=$('planSearch');
 const updateActivityOptions=()=>{
  const q=(search.value||'').trim().toLocaleLowerCase('es');
  const items=state.catalog.filter(c=>c.active!==false&&(!area.value||c.area===area.value)&&[c.name,c.area,c.method,c.code,c.technique].join(' ').toLocaleLowerCase('es').includes(q));
  const selected=activity.value;
  activity.innerHTML='<option value="">'+(items.length?'Seleccione actividad':'Sin coincidencias: registre la actividad en Catálogo Maestro')+'</option>'+items.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(c.area)}</option>`).join('');
  if(items.some(c=>c.id===selected))activity.value=selected;
  activity.onchange?.();
 };
 area.onchange=updateActivityOptions;
 search.oninput=updateActivityOptions;
 $('planAddActivity').onclick=()=>{state.page='Catálogo Maestro';state.catalogFilter=search.value;state.catalogArea=area.value||'TODAS';main();document.querySelector('#addCatalog')?.click()};
 updateActivityOptions();
 $('prepareReception')?.addEventListener('click',()=>{
  const options=state.catalog.filter(c=>c.active!==false&&/recepci[oó]n de muestras/i.test(c.area||'')&&/recepci[oó]n de muestras/i.test(c.name||''));
  if(!options.length){state.planMessage='No se encontraron las modalidades de recepción en el Catálogo Maestro.';main();return;}
  const selected=options.length===1?options[0]:options[Number(prompt('Seleccione recepción:\n'+options.map((c,i)=>(i+1)+'. '+c.name).join('\n')+'\nEscriba el número (1–'+options.length+'):'))-1];
  if(!selected)return;
  area.value=selected.area;updateActivityOptions();activity.value=selected.id;activity.dispatchEvent(new Event('change'));start.value='08:00';start.dispatchEvent(new Event('change'));document.querySelector('#planForm')?.scrollIntoView({behavior:'smooth',block:'center'});
 });
 document.querySelectorAll('[data-auto-ht]').forEach(btn=>btn.onclick=async()=>{
  const id=btn.dataset.autoHt;const rows=state.plans.filter(p=>activePlan(p)&&p.date===state.planDate&&p.analystId===id&&isAnalyticalPlan(p));
  if(!rows.length)return;
  const suggestion=htSuggestion(rows[0],rows[0].id);
  if(!suggestion?.plan){state.planMessage=suggestion?.error||'HT ya reservado.';main();return;}
  btn.disabled=true;btn.textContent='Guardando…';
  try{await savePlan(suggestion.plan,state.user.uid);state.planMessage='HT obligatorio registrado para '+suggestion.plan.analystName+'.';main()}
  catch(e){state.planMessage='No se pudo registrar HT: '+e.message;main()}
 });
 const samples=$('planSamples'),sampleWrap=$('planSamplesWrap'),detail=$('planTimeDetail');
 const recalculate=()=>{const c=state.catalog.find(x=>x.id===activity.value);sampleWrap.hidden=c?.timeModel!=='MUESTRAS';if(!c){detail.textContent='Seleccione una actividad.';validate();return}const d=plannedDuration(c,Number(samples.value));detail.textContent=(c.timeModel||'FIJO')+' · '+d.reason;if(d.minutes!==null){const finish=planEndFor(pmin(start.value),d.minutes);if(finish!==null)end.value=ptime(finish);else detail.textContent+=' · ⚠ No cabe en la jornada; cambie inicio o revise la duración.';}validate()};
 const autoFit=()=>{const c=state.catalog.find(x=>x.id===activity.value),a=planAnalysts().find(x=>x.id===analyst.value);if(!c||!a)return recalculate();const d=plannedDuration(c,Number(samples.value));if(d.minutes===null)return recalculate();const current={date:state.planDate,analystId:a.id,area:c.area,startMin:pmin(start.value),endMin:planEndFor(pmin(start.value),d.minutes)||pmin(end.value)};const suggested=nextPlanSlot(current,d.minutes);if(suggested){start.value=ptime(suggested.startMin);end.value=ptime(suggested.endMin);detail.textContent='✓ Horario disponible seleccionado automáticamente: '+ptime(suggested.startMin)+'–'+ptime(suggested.endMin)+' · '+d.reason;}else{detail.textContent='⚠ No hay un bloque disponible para esta actividad ('+formatDuration(d.minutes)+'). Cambie analista o revise la agenda.';}validate()};
 activity.onchange=autoFit;samples.oninput=autoFit;analyst.onchange=autoFit;start.onchange=recalculate;
 const validate=()=>{const c=state.catalog.find(x=>x.id===activity.value),a=planAnalysts().find(x=>x.id===analyst.value);if(!c||!a){$('planAdvice').textContent='Seleccione actividad y analista.';return}const d=plannedDuration(c,Number(samples.value));const w=planWarnings({date:state.planDate,analystId:a.id,area:c.area,startMin:pmin(start.value),endMin:pmin(end.value)});const proposal={date:state.planDate,analystId:a.id,analystName:a.name||a.email||a.id,activityId:c.id,activityName:c.name,area:c.area,startMin:pmin(start.value),endMin:pmin(end.value)};const ht=htSuggestion(proposal);if(ht?.error)w.push(ht.error);if(ht?.plan)w.push('Se reservará automáticamente HT: '+ptime(ht.plan.startMin)+'–'+ptime(ht.plan.endMin));if(c.timeModel!=='LIBRE'&&(d.minutes===null||planWork(pmin(start.value),pmin(end.value))!==d.minutes))w.push(d.minutes===null?d.reason:'El horario debe coincidir con '+formatDuration(d.minutes)+' configurados en el catálogo.');$('planAdvice').textContent=w.length?'⚠ '+w.join(' · '):'✓ Horario y competencia autorizados · '+d.reason};[start,end].forEach(x=>x.onchange=validate);
 form.onsubmit=async e=>{e.preventDefault();const c=state.catalog.find(x=>x.id===activity.value),a=planAnalysts().find(x=>x.id===analyst.value);if(!c||!a)return alert('Seleccione actividad y analista.');const candidate={date:state.planDate,analystId:a.id,analystName:a.name||a.email||a.id,activityId:c.id,activityName:c.name,area:c.area,startMin:pmin(start.value),endMin:pmin(end.value),durationMin:planWork(pmin(start.value),pmin(end.value)),notes:$('planNotes').value};const calculated=plannedDuration(c,Number(samples.value));const problems=planWarnings(candidate);if(c.timeModel!=='LIBRE'&&(calculated.minutes===null||candidate.durationMin!==calculated.minutes))problems.push(calculated.minutes===null?calculated.reason:'La duración no coincide con la ficha técnica ('+formatDuration(calculated.minutes)+').');const ht=htSuggestion(candidate);if(ht?.error)problems.push(ht.error);if(problems.length)return alert(problems.join('\n'));candidate.timeModel=c.timeModel||'FIJO';candidate.sampleCount=c.timeModel==='MUESTRAS'?Number(samples.value):0;candidate.catalogRevision=Number(c.revision||1);candidate.catalogTechnicalVersion=Number(c.technicalVersion||1);try{await savePlan(candidate,state.user.uid,ht?.plan||null);state.planMessage=ht?.plan?'Ensayo y reserva HT guardados conjuntamente en Firebase.':'Planificación guardada en Firebase.';main()}catch(err){state.planMessage='No se guardó: '+err.message;main()}};
 document.querySelectorAll('[data-cancel-plan]').forEach(b=>b.onclick=async()=>{const p=state.plans.find(x=>x.id===b.dataset.cancelPlan);if(!p||!confirm('¿Cancelar esta asignación? El historial se conservará.'))return;try{await cancelPlan(p,state.user.uid);state.planMessage='Asignación cancelada.';main()}catch(e){alert(e.message)}});
 document.querySelectorAll('[data-reassign]').forEach(b=>b.onclick=async()=>{const p=state.plans.find(x=>x.id===b.dataset.reassign);if(!p)return;const chosen=await selectPlanAnalyst(p);if(!chosen)return;const target=planAnalysts().find(x=>x.id===chosen);if(!target)return alert('Analista no disponible.');const candidate={...p,analystId:target.id,analystName:target.name||target.email,expectedRevision:p.revision};const problems=planWarnings(candidate,p.id);if(problems.length)return alert(problems.join('\n'));try{await savePlan(candidate,state.user.uid);state.planMessage='Reasignación guardada: '+p.analystName+' → '+candidate.analystName+'.';main()}catch(e){alert(e.message)}});
}

