async function refreshEnvironmentalCardTitles(){if(state.page!=='Cartas de Control'||!state.user)return;const buttons=[...document.querySelectorAll('.env-open[data-env-id]')];await Promise.all(buttons.map(async btn=>{try{const snap=await getDoc(doc(db,'environmentalCards',btn.dataset.envId));if(snap.exists()&&snap.data().name){const title=btn.closest('article')?.querySelector('strong');if(title)title.textContent='🌡 '+snap.data().name;}}catch(err){console.warn('No se pudo consultar el nombre de carta:',err.message)}}));}


